import 'fake-indexeddb/auto';
import {ScopedEditorStore} from '../src/sync/editorStore';
import {it,expect} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {newId} from '../src/domain/model';
import type {ProjectData} from '../src/domain/types';
import {bootstrapNativeProject,type AtomicSyncRepository,type ServerIdentity} from '../src/sync/server';
import {applyEditorOperation,readEditorImage} from '../src/sync/editor';
import {createSyncOperation,type SyncOperation} from '../src/sync/protocol';
import {assertAck} from '../src/sync/validation';
const root='/tmp/shinariokanri-independent-rb09-af0c2b9/independent',container='shinariokanri-independent-rb09-af0c2b9',owner:ServerIdentity={accountId:'00000000-0000-4000-8000-000000000001',sessionId:'10000000-0000-4000-8000-000000000001'},editor:ServerIdentity={accountId:'00000000-0000-4000-8000-000000000002',sessionId:'10000000-0000-4000-8000-000000000002'},calls:unknown[]=[];
function arg(v:unknown):string{if(v===null)return'null';if(v&&typeof v==='object'&&'rawSQL'in v)return(v as {rawSQL:string}).rawSQL;return"'"+(typeof v==='object'?JSON.stringify(v):String(v)).replace(/'/g,"''")+"'"+(typeof v==='object'?'::jsonb':'');}
function sql(text:string){const r=spawnSync('docker',['exec','-i',container,'psql','-U','postgres','-qAt','-v','ON_ERROR_STOP=1'],{input:text,encoding:'utf8',timeout:20000,maxBuffer:32*1024*1024});calls.push({sql:text,status:r.status,stdout:r.stdout,stderr:r.stderr});writeFileSync(root+'/sql-authorization-calls.json',JSON.stringify(calls,null,2)+'\n');if(r.status!==0)throw Error(r.stderr||'SQL_CALL_FAILED');return r.stdout;}
function rpc(name:string,values:unknown[]){const out=sql('set role service_role;\nselect public.'+name+'('+values.map(arg).join(',')+')::text;\n').trim();return out?JSON.parse(out):null;}
const repository:AtomicSyncRepository={read:async(i,p,b,o)=>rpc('scenario_sync_engine_context',[i.accountId,i.sessionId,p,b,o]),bootstrap:async(i,v)=>rpc('scenario_sync_bootstrap',[i.accountId,i.sessionId,v.project.projectId,v.project,v.documents,v.worlds]),commit:async(i,v)=>rpc('scenario_sync_commit_prepared',[i.accountId,i.sessionId,v.projectId,v.expectedRevision,v.operation,v.operationHash,v.ack,v.documents,v.image,{rawSQL:'ARRAY['+(v.derivedIds??[]).map(id=>"'"+id+"'").join(',')+']::uuid[]'}])};
function proof(id:string,data:unknown){writeFileSync(root+'/fixtures/'+id+'.json',JSON.stringify(data,null,2)+'\n');}
async function seed(){const f=JSON.parse(readFileSync(root+'/fixtures/native-two-targets.json','utf8')) as {p:ProjectData;idA:string;idB:string};f.p.projectId=newId();f.p.entities.forEach(e=>e.projectId=f.p.projectId);const a=f.p.entities.find(e=>e.id===f.idA)!;a.customValues['private-editor-canary']='PRIVATE_GRANTED_DOC_FIELD';const b=f.p.entities.find(e=>e.id===f.idB)!;b.visibility='private';b.name='PRIVATE_EDITOR_RECORD_CANARY';await bootstrapNativeProject(repository,owner,{project:f.p,worlds:{}});rpc('scenario_membership',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,'editor',null,false,{rawSQL:'array[]::uuid[]'},0]);rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[{id:f.idA,fields:['name']}],1,1]);return f;}
async function rename(f:Awaited<ReturnType<typeof seed>>,name='許可された編集😀'):Promise<SyncOperation>{const image=await readEditorImage(repository,editor,f.p.projectId),base=image.documents[0],local=structuredClone(base);local.fields.name=name;return createSyncOperation({scope:{accountId:editor.accountId,projectId:f.p.projectId},baseRevision:image.serverRevision,operationId:newId(),targets:[{base,local}]});}
it('R9SAV01 identical granted fields with a changed membership epoch refuse the entire prepared SQL batch before document or operation evidence writes',async()=>{const f=await seed(),op=await rename(f),before=await repository.read(owner,f.p.projectId,null,null),guarded:AtomicSyncRepository={...repository,commit:async(i,v)=>{rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[{id:f.idA,fields:['name']}],1,2]);return repository.commit(i,v);}};await expect(applyEditorOperation(guarded,editor,op)).rejects.toThrow('REVISION_CHANGED');const after=await repository.read(owner,f.p.projectId,null,op.operationId);expect(after.documents).toEqual(before.documents);expect(after.serverRevision).toBe('1');expect(after.previousAck).toBe(null);expect((after as typeof after & {authorizationRevision:string}).authorizationRevision).toBe('3');proof('R9SAV01',{operation:op,before,after,expected:'changed permission epoch rejects all prepared mutations'});});
it('R9SAV02 SQL stamped field withdrawal and explicit regrant at one content revision reject the old expanded image and then resume exactly the new current grant',async()=>{const f=await seed(),initial=await readEditorImage(repository,editor,f.p.projectId),cache=new ScopedEditorStore(editor.accountId);try{expect(initial.authorizationRevision).toBe('2');await cache.receive(initial);rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[],1,2]);const reduced=await readEditorImage(repository,editor,f.p.projectId);expect(reduced.authorizationRevision).toBe('3');expect(reduced.serverRevision).toBe('1');expect(reduced.documents).toEqual([]);await cache.receive(reduced);const before=await cache.get(f.p.projectId);await expect(cache.receive(initial)).rejects.toMatchObject({code:'REVISION_CHANGED'});expect(await cache.get(f.p.projectId)).toEqual(before);rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[{id:f.idA,fields:['name']}],1,3]);const regrant=await readEditorImage(repository,editor,f.p.projectId);expect(regrant.authorizationRevision).toBe('4');expect(regrant.serverRevision).toBe('1');await cache.receive(regrant);const after=await cache.get(f.p.projectId);expect(after!.documents).toEqual(regrant.documents);proof('R9SAV02',{initial,reduced,before,regrant,after});}finally{await cache.delete();}});
it('R9SAV03 a scope deadline crossing after service validation is checked again in the locked commit and refuses document, revision and receipt mutation',async()=>{const f=await seed(),op=await rename(f),before=await repository.read(owner,f.p.projectId,null,null),guarded:AtomicSyncRepository={...repository,commit:async(i,v)=>{sql("update scenario_private.editor_scopes set expires_at=clock_timestamp()-interval '1 second' where project_id='"+f.p.projectId+"' and account_id='"+editor.accountId+"';");return repository.commit(i,v);}};await expect(applyEditorOperation(guarded,editor,op)).rejects.toThrow('FORBIDDEN');const after=await repository.read(owner,f.p.projectId,null,op.operationId);expect(after.documents).toEqual(before.documents);expect(after.serverRevision).toBe('1');expect(after.previousAck).toBe(null);proof('R9SAV03',{operation:op,before,after,expected:'expired field scope refuses entire SQL batch'});});
